INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_crafted_unique_kurzschwert','An archaic saber, masterfully crafted from one of the Purplewyrm Japhgur''s knife-like teeth.\n\nEffect: AT/PA +1 and 5% chance of wounds');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_crafted_unique_wurmspiess','An archaic pole weapon, expertly crafted from one of the Purplewyrm Japhgur''s knife-like teeth.\n\nEffect: 5% chance of wounds');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_crafted_unique_bogen','An expertly crafted composite bow of metal, premium wood, and horn from the Purplewyrm Japhgur.\n\nReload time: 1 CR');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_crafted_unique_armbrust','An expertly crafted crossbow of metal and horn from the Purplewyrm Japhgur.\n\nReload time: 4 CR');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_saebel','A masterfully crafted saber from the embers of the Fire Falls of Algormosh. The weapon lies featherlight in the hand and the slender blade is razor sharp.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_schwert','This Longsword was forged by a master from the embers of the Fire Falls of Algormosh. The glittering metal is almost weightless in the hand and the thin blade is unequalled in its sharpness.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_axt','An axe masterfully crafted from the embers of the Fire Falls of Algormosh. The glittering metal is almost weightless in the hand and the thin blade is unequalled in its sharpness.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_zweihandschwert','Flamestrike'' - is the worthy name of this masterfully crafted two-handed sword from the embers of the Fire Falls of Algormosh. The gleaming metal is wonderfully light and the slender, yet extremely strong, blade is so sharp that it slices through armor as effortlessly as a hot knife through butter.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_zweihandaxt','The dual blade of this axe from the embers of the Fire Falls of Algormosh is made of glittering metal. The blades are sharper than any razor and this weapon''s balance is incomparable.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_speer','Firespike'' - is the name given to this masterfully crafted spear from the embers of the Fire Falls of Algormosh. This spear is almost weightless and is perfectly balanced. Its point is sharp enough to effortlessly penetrate any material, including the toughest steel.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_schwererdolch','This Heavy Dagger was forged by a master in the embers of the Fire Falls of Algormosh. The glittering metal is barely discernable in the hand and the thin blade is so sharp that this dagger should be used only with care.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_rapier','Sparksting'' - is the extremely apt name for this masterfully-crafted rapier. The gleaming metal lies almost weightless in the hand and the slim blade is of an unparalleled sharpness and elegance.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_stab','This fighting staff was forged from the embers of the Fire Falls of Algormosh. It glitters in the sun and rests perfectly balanced in the hand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_bogen','This Cyclopean Composite Bow was crafted by a master from the finest Aventurian woods and magical titanium. It is very light and flexible. It is also effortlessly drawn, as if by a magic hand.\n\nReload time: 0 CR');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_armbrust','Flamesnap'' is the worthy name of this cyclopean crossbow, masterfully crafted from the finest Aventurian woods and gleaming steel from the embers of the Fire Falls of Algormosh. This crossbow lies almost weightless in the hand and can be pulled without expending much energy.\n\nFire rate: 2 CR');
